import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

type Interval = [number, number];

function canAttendMeetings(intervals: Interval[]): boolean {
  intervals.sort((a, b) => a[0] - b[0]);
  let previousEnd = -Infinity;
  for (const [start, end] of intervals) {
    if (start < previousEnd) {
      return false;
    }
    previousEnd = end;
  }
  return true;
}

const lines = input.trim().split("\n");
const n = Number(lines[0] ?? "0");
const intervals = lines.slice(1, n + 1).map((line): Interval => {
  const [start = 0, end = 0] = line.trim().split(/\s+/).map(Number);
  return [start, end];
});
console.log(canAttendMeetings(intervals) ? "true" : "false");
